import csv

from django.http import HttpResponse

from shop.models import Author, Book


def _csv_export(filename, header, rows):
    response = HttpResponse(content_type='text/csv')
    response['Content-Disposition'] = f'attachment; filename="{filename}"'
    writer = csv.writer(response)
    writer.writerow(header)
    for row in rows:
        writer.writerow(row)
    return response


def export_books_csv(request):
    return _csv_export('books.csv', ['title', 'year'],
                       ((b.title, b.year) for b in Book.objects.order_by('title')))


def export_authors_csv(request):
    return _csv_export('authors.csv', ['name', 'country'],
                       ((a.name, a.country) for a in Author.objects.order_by('name')))

